import{_ as i,C as r,o as t,c as s,a2 as e,b as o,w as d,a as l,E as f,a3 as c}from"./chunks/framework.CZqXuAiL.js";const k=JSON.parse('{"title":"Bandwidth Manager","description":"Production-grade Docker bandwidth management with per-container speed limits, daily traffic quotas, and kernel-level tc enforcement.","frontmatter":{"title":"Bandwidth Manager","description":"Production-grade Docker bandwidth management with per-container speed limits, daily traffic quotas, and kernel-level tc enforcement.","head":[["meta",{"name":"og:title","content":"Bandwidth Manager — Docker Traffic Control"}],["meta",{"name":"og:description","content":"Per-container speed limits, daily quotas, kernel-level tc enforcement, webhook notifications. Built for production."}]]},"headers":[],"relativePath":"bandwidth-manager/index.md","filePath":"bandwidth-manager/index.md","lastUpdated":1783232968000}'),v={name:"bandwidth-manager/index.md"};function h(g,a,p,u,m,b){const n=r("Mermaid");return t(),s("div",null,[a[1]||(a[1]=e(`<h1 id="bandwidth-manager" tabindex="-1" data-v-83aa3f3e>Bandwidth Manager <a class="header-anchor" href="#bandwidth-manager" aria-label="Permalink to &quot;Bandwidth Manager&quot;" data-v-83aa3f3e>​</a></h1><p data-v-83aa3f3e><strong data-v-83aa3f3e>Production-grade Docker bandwidth management</strong> — per-container speed limits, daily traffic quotas, kernel‑level <code data-v-83aa3f3e>tc</code> enforcement.</p><p data-v-83aa3f3e>Stop guessing which container is saturating your uplink. Bandwidth Manager gives you surgical control over every container&#39;s network throughput — programmatically, persistently, and with zero userspace throttling overhead.</p><div class="tip custom-block" style="margin-top:1.5rem;" data-v-83aa3f3e><p data-v-83aa3f3e><strong data-v-83aa3f3e>🎯 Built for ALTIS TECH SOLUTIONS by <a href="https://github.com/AnAverageBeing" target="_blank" rel="noreferrer" data-v-83aa3f3e>AnAverageBeing</a></strong><br data-v-83aa3f3e><a href="https://github.com/AnAverageBeing/Bandwidth-flow-maintainer" target="_blank" rel="noreferrer" data-v-83aa3f3e>GitHub Repo</a> · <code data-v-83aa3f3e>MIT License</code></p></div><hr data-v-83aa3f3e><h2 id="why-bandwidth-manager" tabindex="-1" data-v-83aa3f3e>Why Bandwidth Manager? <a class="header-anchor" href="#why-bandwidth-manager" aria-label="Permalink to &quot;Why Bandwidth Manager?&quot;" data-v-83aa3f3e>​</a></h2><p data-v-83aa3f3e>Running multiple Docker containers on a single host means one noisy neighbour can starve everyone else. Traditional solutions are painful:</p><table tabindex="0" data-v-83aa3f3e><thead data-v-83aa3f3e><tr data-v-83aa3f3e><th data-v-83aa3f3e>Approach</th><th data-v-83aa3f3e>Pain Point</th></tr></thead><tbody data-v-83aa3f3e><tr data-v-83aa3f3e><td data-v-83aa3f3e><strong data-v-83aa3f3e>Manual <code data-v-83aa3f3e>tc</code></strong></td><td data-v-83aa3f3e>Steep learning curve, ephemeral rules lost on reboot, no per‑container visibility</td></tr><tr data-v-83aa3f3e><td data-v-83aa3f3e><strong data-v-83aa3f3e>cgroups v2</strong></td><td data-v-83aa3f3e>Inconsistent across kernel versions, no daily quota concept, poor tooling</td></tr><tr data-v-83aa3f3e><td data-v-83aa3f3e><strong data-v-83aa3f3e>Docker Compose <code data-v-83aa3f3e>deploy.resources.limits</code></strong></td><td data-v-83aa3f3e>Swarm-only, ignores standalone containers, no traffic accounting</td></tr><tr data-v-83aa3f3e><td data-v-83aa3f3e><strong data-v-83aa3f3e>Thick SaaS agents</strong></td><td data-v-83aa3f3e>Expensive, closed-source, heavy on RAM</td></tr></tbody></table><p data-v-83aa3f3e>Bandwidth Manager fills the gap with a <strong data-v-83aa3f3e>single static binary</strong>, a handful of Docker labels, and the Linux kernel&#39;s battle-tested Traffic Control subsystem.</p><hr data-v-83aa3f3e><h2 id="key-features" tabindex="-1" data-v-83aa3f3e>Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;" data-v-83aa3f3e>​</a></h2><h3 id="🚦-per-container-speed-limiting" tabindex="-1" data-v-83aa3f3e>🚦 Per-Container Speed Limiting <a class="header-anchor" href="#🚦-per-container-speed-limiting" aria-label="Permalink to &quot;🚦 Per-Container Speed Limiting&quot;" data-v-83aa3f3e>​</a></h3><p data-v-83aa3f3e>Set upload and download rate limits <strong data-v-83aa3f3e>per container</strong> via Docker labels. No config files, no sidecars.</p><div class="language-yaml vp-adaptive-theme" data-v-83aa3f3e><button title="Copy Code" class="copy" data-v-83aa3f3e></button><span class="lang" data-v-83aa3f3e>yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0" data-v-83aa3f3e><code data-v-83aa3f3e><span class="line" data-v-83aa3f3e><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;" data-v-83aa3f3e>labels</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;" data-v-83aa3f3e>:</span></span>
<span class="line" data-v-83aa3f3e><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;" data-v-83aa3f3e>  bwm.limit.down</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;" data-v-83aa3f3e>: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;" data-v-83aa3f3e>&quot;50mbps&quot;</span></span>
<span class="line" data-v-83aa3f3e><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;" data-v-83aa3f3e>  bwm.limit.up</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;" data-v-83aa3f3e>:   </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;" data-v-83aa3f3e>&quot;10mbps&quot;</span></span></code></pre></div><h3 id="📊-daily-traffic-quotas" tabindex="-1" data-v-83aa3f3e>📊 Daily Traffic Quotas <a class="header-anchor" href="#📊-daily-traffic-quotas" aria-label="Permalink to &quot;📊 Daily Traffic Quotas&quot;" data-v-83aa3f3e>​</a></h3><p data-v-83aa3f3e>Define a total data allowance that resets at midnight (configurable). Containers that exceed their quota are throttled to a trickle until the next reset window.</p><div class="language-yaml vp-adaptive-theme" data-v-83aa3f3e><button title="Copy Code" class="copy" data-v-83aa3f3e></button><span class="lang" data-v-83aa3f3e>yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0" data-v-83aa3f3e><code data-v-83aa3f3e><span class="line" data-v-83aa3f3e><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;" data-v-83aa3f3e>labels</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;" data-v-83aa3f3e>:</span></span>
<span class="line" data-v-83aa3f3e><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;" data-v-83aa3f3e>  bwm.quota.daily</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;" data-v-83aa3f3e>: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;" data-v-83aa3f3e>&quot;5gb&quot;</span></span></code></pre></div><h3 id="🔍-automatic-container-discovery" tabindex="-1" data-v-83aa3f3e>🔍 Automatic Container Discovery <a class="header-anchor" href="#🔍-automatic-container-discovery" aria-label="Permalink to &quot;🔍 Automatic Container Discovery&quot;" data-v-83aa3f3e>​</a></h3><p data-v-83aa3f3e>Listens to the Docker event stream. New containers get rules applied immediately. Stopped containers get cleaned up. No polling, no cron.</p><h3 id="⚡-kernel-level-tc-enforcement" tabindex="-1" data-v-83aa3f3e>⚡ Kernel-Level <code data-v-83aa3f3e>tc</code> Enforcement <a class="header-anchor" href="#⚡-kernel-level-tc-enforcement" aria-label="Permalink to &quot;⚡ Kernel-Level \`tc\` Enforcement&quot;" data-v-83aa3f3e>​</a></h3><p data-v-83aa3f3e>All shaping runs through the Linux <code data-v-83aa3f3e>tc</code> (Traffic Control) subsystem via <code data-v-83aa3f3e>htb</code> qdiscs and <code data-v-83aa3f3e>fq_codel</code> inner qdiscs attached to veth pairs. <strong data-v-83aa3f3e>Zero userspace throttling</strong> — the kernel does the heavy lifting, so CPU overhead is negligible even at multi‑gigabit rates.</p><h3 id="🏷️-docker-label-overrides" tabindex="-1" data-v-83aa3f3e>🏷️ Docker Label Overrides <a class="header-anchor" href="#🏷️-docker-label-overrides" aria-label="Permalink to &quot;🏷️ Docker Label Overrides&quot;" data-v-83aa3f3e>​</a></h3><p data-v-83aa3f3e>Every setting can be driven by Docker container labels. Tweak limits without restarting the daemon — just update the label and send <code data-v-83aa3f3e>SIGHUP</code>.</p><h3 id="🔔-webhook-notifications" tabindex="-1" data-v-83aa3f3e>🔔 Webhook Notifications <a class="header-anchor" href="#🔔-webhook-notifications" aria-label="Permalink to &quot;🔔 Webhook Notifications&quot;" data-v-83aa3f3e>​</a></h3><p data-v-83aa3f3e>Fire alerts to <strong data-v-83aa3f3e>Discord</strong> or <strong data-v-83aa3f3e>Slack</strong> when containers hit quota thresholds or when the daemon state changes. Includes a rich embed payload.</p><h3 id="🖥️-modern-terminal-ui" tabindex="-1" data-v-83aa3f3e>🖥️ Modern Terminal UI <a class="header-anchor" href="#🖥️-modern-terminal-ui" aria-label="Permalink to &quot;🖥️ Modern Terminal UI&quot;" data-v-83aa3f3e>​</a></h3><p data-v-83aa3f3e>A beautiful, keyboard‑driven TUI built with <a href="https://github.com/charmbracelet/bubbletea" target="_blank" rel="noreferrer" data-v-83aa3f3e>Bubble Tea</a>. Inspect live rates, quotas, and rule status in real time. Sort, filter, and drill down — all from your terminal.</p><h3 id="📈-historical-stats" tabindex="-1" data-v-83aa3f3e>📈 Historical Stats <a class="header-anchor" href="#📈-historical-stats" aria-label="Permalink to &quot;📈 Historical Stats&quot;" data-v-83aa3f3e>​</a></h3><p data-v-83aa3f3e>Per‑container byte counters and rate samples persisted to <strong data-v-83aa3f3e>SQLite</strong> (zero external dependencies). Query with the CLI or export to CSV for Grafana.</p><h3 id="🧩-sqlite-backend-—-zero-external-dependencies" tabindex="-1" data-v-83aa3f3e>🧩 SQLite Backend — Zero External Dependencies <a class="header-anchor" href="#🧩-sqlite-backend-—-zero-external-dependencies" aria-label="Permalink to &quot;🧩 SQLite Backend — Zero External Dependencies&quot;" data-v-83aa3f3e>​</a></h3><p data-v-83aa3f3e>No Postgres, no Redis, no message queues. Everything lives in a single <code data-v-83aa3f3e>bandwidth.db</code> file. Back it up with <code data-v-83aa3f3e>rsync</code> and sleep easy.</p><h3 id="🔧-systemd-integration" tabindex="-1" data-v-83aa3f3e>🔧 Systemd Integration <a class="header-anchor" href="#🔧-systemd-integration" aria-label="Permalink to &quot;🔧 Systemd Integration&quot;" data-v-83aa3f3e>​</a></h3><p data-v-83aa3f3e>Ships with a hardened systemd unit. Socket activation, <code data-v-83aa3f3e>ProtectSystem=strict</code>, <code data-v-83aa3f3e>NoNewPrivileges</code>, and automatic restarts.</p><hr data-v-83aa3f3e><h2 id="quick-install" tabindex="-1" data-v-83aa3f3e>Quick Install <a class="header-anchor" href="#quick-install" aria-label="Permalink to &quot;Quick Install&quot;" data-v-83aa3f3e>​</a></h2><div class="language-bash vp-adaptive-theme" data-v-83aa3f3e><button title="Copy Code" class="copy" data-v-83aa3f3e></button><span class="lang" data-v-83aa3f3e>bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0" data-v-83aa3f3e><code data-v-83aa3f3e><span class="line" data-v-83aa3f3e><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;" data-v-83aa3f3e>curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;" data-v-83aa3f3e> -sSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;" data-v-83aa3f3e> https://raw.githubusercontent.com/AnAverageBeing/Bandwidth-flow-maintainer/main/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;" data-v-83aa3f3e> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;" data-v-83aa3f3e> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;" data-v-83aa3f3e> bash</span></span></code></pre></div><p data-v-83aa3f3e>That&#39;s it. The script installs the binary, drops in a systemd unit, and starts the daemon. Head over to <a href="./getting-started/installation" data-v-83aa3f3e>Installation</a> for the full walkthrough and manual install instructions.</p><hr data-v-83aa3f3e><h2 id="architecture" tabindex="-1" data-v-83aa3f3e>Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;" data-v-83aa3f3e>​</a></h2>`,39)),(t(),o(c,null,{default:d(()=>[f(n,{id:"mermaid-148",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20subgraph%20Host%5B%22Host%20(Container%20Runtime)%22%5D%0A%20%20%20%20%20%20%20%20direction%20TB%0A%20%20%20%20%20%20%20%20DE%5B%22Docker%20Engine%20%2Fcontainerd%22%5D%0A%20%20%20%20%20%20%20%20DE%20--%3E%7C%22event%20stream%22%7C%20DISC%5B%22Container%20Discovery%22%5D%0A%20%20%20%20%20%20%20%20DISC%20--%3E%7C%22label%20parsing%22%7C%20RULES%5B%22Rule%20Builder%22%5D%0A%20%20%20%20%20%20%20%20RULES%20--%3E%7C%22htb%20%2B%20fq_codel%22%7C%20TC%5B%22tc%20Subsystem%22%5D%0A%20%20%20%20%20%20%20%20TC%20--%3E%7C%22attached%20to%22%7C%20VETH%5B%22veth%20Pairs%22%5D%0A%20%20%20%20%20%20%20%20VETH%20--%3E%20C1%5B%22Container%20A%22%5D%0A%20%20%20%20%20%20%20%20VETH%20--%3E%20C2%5B%22Container%20B%22%5D%0A%20%20%20%20%20%20%20%20VETH%20--%3E%20C3%5B%22Container%20C%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20Userspace%5B%22Userspace%20Layer%22%5D%0A%20%20%20%20%20%20%20%20direction%20TB%0A%20%20%20%20%20%20%20%20CLI%5B%22bwm%20CLI%22%5D%20--%3E%7C%22gRPC%20%2F%20HTTP%22%7C%20SOCKET%5B%22Unix%20Socket%22%5D%0A%20%20%20%20%20%20%20%20TUI%5B%22bwm%20tui%22%5D%20--%3E%20SOCKET%0A%20%20%20%20%20%20%20%20SOCKET%20--%3E%20DAEMON%5B%22bwm-daemon%22%5D%0A%20%20%20%20%20%20%20%20DAEMON%20--%3E%20DE%0A%20%20%20%20%20%20%20%20DAEMON%20--%3E%20SQLITE%5B%22bandwidth.db%22%5D%0A%20%20%20%20%20%20%20%20DAEMON%20--%3E%20WEBHOOK%5B%22Webhook%20Dispatcher%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20Host%20--%3E%20Userspace%0A%20%20%20%20WEBHOOK%20--%3E%20DISCORD%5B%22Discord%22%5D%0A%20%20%20%20WEBHOOK%20--%3E%20SLACK%5B%22Slack%22%5D%0A"})]),fallback:d(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h3 id="control-flow" tabindex="-1" data-v-83aa3f3e>Control Flow <a class="header-anchor" href="#control-flow" aria-label="Permalink to &quot;Control Flow&quot;" data-v-83aa3f3e>​</a></h3><table tabindex="0" data-v-83aa3f3e><thead data-v-83aa3f3e><tr data-v-83aa3f3e><th data-v-83aa3f3e>Path</th><th data-v-83aa3f3e>Description</th></tr></thead><tbody data-v-83aa3f3e><tr data-v-83aa3f3e><td data-v-83aa3f3e><strong data-v-83aa3f3e>Docker → Discovery</strong></td><td data-v-83aa3f3e>Daemon subscribes to <code data-v-83aa3f3e>/events</code>. Container create/destroy triggers re‑eval.</td></tr><tr data-v-83aa3f3e><td data-v-83aa3f3e><strong data-v-83aa3f3e>Discovery → Rules</strong></td><td data-v-83aa3f3e>Labels are parsed into rate &amp; quota specs. Defaults fill in missing values.</td></tr><tr data-v-83aa3f3e><td data-v-83aa3f3e><strong data-v-83aa3f3e>Rules → tc</strong></td><td data-v-83aa3f3e><code data-v-83aa3f3e>htb</code> class tree is built per interface; <code data-v-83aa3f3e>fq_codel</code> leaf qdiscs handle fairness.</td></tr><tr data-v-83aa3f3e><td data-v-83aa3f3e><strong data-v-83aa3f3e>tc → veth → Container</strong></td><td data-v-83aa3f3e>Shaping happens on the host-side veth, so the container has no visibility into the limit — it simply sees a constrained pipe.</td></tr><tr data-v-83aa3f3e><td data-v-83aa3f3e><strong data-v-83aa3f3e>CLI → Unix Socket → Daemon</strong></td><td data-v-83aa3f3e>All administrative commands flow over a Unix socket with filesystem ACLs. No network exposure by default.</td></tr></tbody></table><hr data-v-83aa3f3e><h2 id="comparison" tabindex="-1" data-v-83aa3f3e>Comparison <a class="header-anchor" href="#comparison" aria-label="Permalink to &quot;Comparison&quot;" data-v-83aa3f3e>​</a></h2><table tabindex="0" data-v-83aa3f3e><thead data-v-83aa3f3e><tr data-v-83aa3f3e><th data-v-83aa3f3e>Capability</th><th style="text-align:center;" data-v-83aa3f3e>Bandwidth Manager</th><th style="text-align:center;" data-v-83aa3f3e>Manual <code data-v-83aa3f3e>tc</code></th><th style="text-align:center;" data-v-83aa3f3e>cgroups v2</th><th style="text-align:center;" data-v-83aa3f3e>Docker Compose Limits</th></tr></thead><tbody data-v-83aa3f3e><tr data-v-83aa3f3e><td data-v-83aa3f3e>Per‑container rate limit</td><td style="text-align:center;" data-v-83aa3f3e>✅</td><td style="text-align:center;" data-v-83aa3f3e>✅</td><td style="text-align:center;" data-v-83aa3f3e>⚠️ partial</td><td style="text-align:center;" data-v-83aa3f3e>✅ (Swarm only)</td></tr><tr data-v-83aa3f3e><td data-v-83aa3f3e>Daily traffic quota</td><td style="text-align:center;" data-v-83aa3f3e>✅</td><td style="text-align:center;" data-v-83aa3f3e>❌</td><td style="text-align:center;" data-v-83aa3f3e>❌</td><td style="text-align:center;" data-v-83aa3f3e>❌</td></tr><tr data-v-83aa3f3e><td data-v-83aa3f3e>Automatic container discovery</td><td style="text-align:center;" data-v-83aa3f3e>✅</td><td style="text-align:center;" data-v-83aa3f3e>❌</td><td style="text-align:center;" data-v-83aa3f3e>❌</td><td style="text-align:center;" data-v-83aa3f3e>❌</td></tr><tr data-v-83aa3f3e><td data-v-83aa3f3e>Persistent across reboots</td><td style="text-align:center;" data-v-83aa3f3e>✅</td><td style="text-align:center;" data-v-83aa3f3e>❌</td><td style="text-align:center;" data-v-83aa3f3e>✅</td><td style="text-align:center;" data-v-83aa3f3e>✅</td></tr><tr data-v-83aa3f3e><td data-v-83aa3f3e>Docker label driven</td><td style="text-align:center;" data-v-83aa3f3e>✅</td><td style="text-align:center;" data-v-83aa3f3e>❌</td><td style="text-align:center;" data-v-83aa3f3e>❌</td><td style="text-align:center;" data-v-83aa3f3e>❌</td></tr><tr data-v-83aa3f3e><td data-v-83aa3f3e>Webhook notifications</td><td style="text-align:center;" data-v-83aa3f3e>✅</td><td style="text-align:center;" data-v-83aa3f3e>❌</td><td style="text-align:center;" data-v-83aa3f3e>❌</td><td style="text-align:center;" data-v-83aa3f3e>❌</td></tr><tr data-v-83aa3f3e><td data-v-83aa3f3e>Built‑in TUI</td><td style="text-align:center;" data-v-83aa3f3e>✅</td><td style="text-align:center;" data-v-83aa3f3e>❌</td><td style="text-align:center;" data-v-83aa3f3e>❌</td><td style="text-align:center;" data-v-83aa3f3e>❌</td></tr><tr data-v-83aa3f3e><td data-v-83aa3f3e>Historical stats (SQLite)</td><td style="text-align:center;" data-v-83aa3f3e>✅</td><td style="text-align:center;" data-v-83aa3f3e>❌</td><td style="text-align:center;" data-v-83aa3f3e>❌</td><td style="text-align:center;" data-v-83aa3f3e>❌</td></tr><tr data-v-83aa3f3e><td data-v-83aa3f3e>Works on standalone <code data-v-83aa3f3e>docker run</code></td><td style="text-align:center;" data-v-83aa3f3e>✅</td><td style="text-align:center;" data-v-83aa3f3e>✅</td><td style="text-align:center;" data-v-83aa3f3e>✅</td><td style="text-align:center;" data-v-83aa3f3e>❌</td></tr><tr data-v-83aa3f3e><td data-v-83aa3f3e>Kernel‑level enforcement</td><td style="text-align:center;" data-v-83aa3f3e>✅</td><td style="text-align:center;" data-v-83aa3f3e>✅</td><td style="text-align:center;" data-v-83aa3f3e>✅</td><td style="text-align:center;" data-v-83aa3f3e>❌ (userspace proxy)</td></tr><tr data-v-83aa3f3e><td data-v-83aa3f3e>Learning curve</td><td style="text-align:center;" data-v-83aa3f3e>Low</td><td style="text-align:center;" data-v-83aa3f3e>Steep</td><td style="text-align:center;" data-v-83aa3f3e>Moderate</td><td style="text-align:center;" data-v-83aa3f3e>Low</td></tr></tbody></table><blockquote data-v-83aa3f3e><p data-v-83aa3f3e><strong data-v-83aa3f3e>Bottom line:</strong> If you need simple rate caps <em data-v-83aa3f3e>and</em> daily quotas with zero‑touch operation, Bandwidth Manager is purpose‑built for the job.</p></blockquote><hr data-v-83aa3f3e><h2 id="next-steps" tabindex="-1" data-v-83aa3f3e>Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;" data-v-83aa3f3e>​</a></h2><ul data-v-83aa3f3e><li data-v-83aa3f3e><strong data-v-83aa3f3e><a href="./getting-started/installation" data-v-83aa3f3e>Installation →</a></strong> — Get up and running in under a minute.</li><li data-v-83aa3f3e><strong data-v-83aa3f3e><a href="./configuration" data-v-83aa3f3e>Configuration →</a></strong> — Learn about labels, quotas, and webhooks.</li><li data-v-83aa3f3e><strong data-v-83aa3f3e><a href="./cli" data-v-83aa3f3e>CLI Reference →</a></strong> — Every command, flag, and exit code.</li><li data-v-83aa3f3e><strong data-v-83aa3f3e><a href="./tui" data-v-83aa3f3e>TUI Guide →</a></strong> — Master the terminal dashboard.</li></ul><hr data-v-83aa3f3e><div class="footer-note" data-v-83aa3f3e><p data-v-83aa3f3e><strong data-v-83aa3f3e>Developed by <a href="https://github.com/AnAverageBeing" target="_blank" rel="noreferrer" data-v-83aa3f3e>AnAverageBeing</a> for <a href="https://github.com/pingless-studios" target="_blank" rel="noreferrer" data-v-83aa3f3e>ALTIS TECH SOLUTIONS</a></strong></p><p data-v-83aa3f3e>Crafted with ❤️ and lots of <code data-v-83aa3f3e>tc filter add dev …</code> commands.<br data-v-83aa3f3e> If this project saves you from a 3 AM pager, consider starring the repo.</p></div>',11))])}const x=i(v,[["render",h],["__scopeId","data-v-83aa3f3e"]]);export{k as __pageData,x as default};
